import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.DMtjdCb-.js";const i="/help/assets/collection-detail.en.BKvUg8HW.png",s="/help/assets/external-folders.en.Ccpio4Kf.svg",r="/help/assets/collection-editions.en.MDhocGTm.png",f=JSON.parse('{"title":"7. Existing collections","description":"","frontmatter":{},"headers":[],"relativePath":"en/collections.md","filePath":"en/collections.md"}'),d={name:"en/collections.md"};function l(c,e,h,p,m,g){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="_7-existing-collections" tabindex="-1">7. Existing collections <a class="header-anchor" href="#_7-existing-collections" aria-label="Permalink to &quot;7. Existing collections&quot;">​</a></h1><p>Connect media already on disk while retaining its folder structure. AnimeMachine recognizes ordinary title folders, nested folders, and collections with DVD, BD, or multiple release groups. Choose the source and edition when playing.</p><h2 id="choose-how-to-connect" tabindex="-1">Choose how to connect <a class="header-anchor" href="#choose-how-to-connect" aria-label="Permalink to &quot;Choose how to connect&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you want</th><th>Setting</th></tr></thead><tbody><tr><td>Browse and play an existing collection in place</td><td><strong>Map external read-only library</strong></td></tr><tr><td>Organize new downloads with AnimeMachine</td><td><strong>Anime library path</strong></td></tr><tr><td>Use media downloaded by Ani-RSS</td><td>Its media folder or remote media access</td></tr></tbody></table><p>For an established collection, start with the read-only connection. Check identification and playback before choosing any organization tasks.</p><h2 id="add-your-folder" tabindex="-1">Add your folder <a class="header-anchor" href="#add-your-folder" aria-label="Permalink to &quot;Add your folder&quot;">​</a></h2><ol><li>Open <strong>Settings → Connections</strong>.</li><li>Enable <strong>Map external read-only library</strong> and enter a media folder accessible to the app.</li><li>Save and let the background inventory complete.</li><li>Search for one of its titles, open details, and check playback sources and episodes.</li></ol><p><img src="'+i+'" alt="Existing media: recognized sources and episodes" loading="lazy"></p><p>Scanning includes subfolders and separates main episodes from extras such as NCOP, NCED, and trailers. Names should identify the title, season, or episode; check the matched title in details when names are ambiguous.</p><h2 id="docker-folders" tabindex="-1">NAS paths and container paths <a class="header-anchor" href="#docker-folders" aria-label="Permalink to &quot;NAS paths and container paths {#docker-folders}&quot;">​</a></h2><p>Docker first mounts a NAS folder into the container; the app settings use the container path. For example:</p><table tabindex="0"><thead><tr><th>Folder on the NAS</th><th>Container path</th><th>Enter in settings</th></tr></thead><tbody><tr><td><code>/volume1/anime</code></td><td><code>/External</code></td><td><code>/External</code></td></tr><tr><td>Project&#39;s <code>library</code> folder</td><td><code>/Library</code></td><td><code>/Library</code></td></tr></tbody></table><p><img src="'+s+'" alt="Folder mapping: NAS folders and container paths" loading="lazy"></p><p>For the default stack, create <code>.env</code> next to <code>compose.yaml</code> with your existing media folder:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ANM_EXTERNAL_LIBRARY_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/volume1/anime</span></span></code></pre></div><p>Run <code>docker compose up -d</code> there, then enable the external library in AnimeMachine. Replace <code>/volume1/anime</code> with the actual folder shown in your NAS file manager.</p><p>On Windows, enter <code>C:\\Anime</code> or <code>\\\\NAS\\Anime</code> directly. Network shares must be accessible to the Windows account running AnimeMachine. Access or quiet-hours status appears below each path; save edited paths before checking them.</p><h2 id="select-an-edition" tabindex="-1">Select an edition <a class="header-anchor" href="#select-an-edition" aria-label="Permalink to &quot;Select an edition&quot;">​</a></h2><ol><li>Open the recognized title.</li><li>Choose the media source, then select a release group, DVD/BD format, or quality in the edition dropdown.</li><li>Check the available episodes and open your player.</li></ol><p><img src="'+r+'" alt="Edition selection: separate DVD, BD, and release-group versions" loading="lazy"></p><p><strong>Expected result:</strong> Playback lists the chosen edition&#39;s episodes and opens that edition. <strong>Automatic</strong> chooses an available edition for each episode.</p><h2 id="files-are-missing-from-the-page" tabindex="-1">Files are missing from the page <a class="header-anchor" href="#files-are-missing-from-the-page" aria-label="Permalink to &quot;Files are missing from the page&quot;">​</a></h2><p>During the initial scan, Playback shows inventory preparation. If files remain missing afterward, check the folder, mount, and readable status in <strong>Settings → Connections</strong>, then review title and episode naming. Quiet hours and temporary disconnections retain the existing inventory; access resumes when the folder is available.</p>',23)])])}const b=t(d,[["render",l]]);export{f as __pageData,b as default};
